10: /// </summary>
11: /// <remarks>
12: /// Requirement coverage: TR-MCP-REPL-001 AC-002 (hostile validation round 7: both variables at 2147483647 made 19 REPL
13: /// unit cases throw ArgumentOutOfRangeException from CancellationTokenSource.CancelAfter;
14: /// triage-report-c993b9446bb8464ba375f74fabd07dad), and through it TR-MCP-USECASE-018 AC-006 and TR-MCP-USECASE-019
15: /// AC-008 (a unit test may reach code that reads an environment variable only where its outcome does not change).
16: /// Test data: a table of scripted configured values with the timeout each must give, run against a parse function
17: /// passed in, so the contract is proved on a scripted reference parser with negative controls before the production
18: /// parser exists; no test reads or writes the process environment.
19: /// </remarks>
20: public sealed class ReplCommandTimeoutTests
21: {
22:     private static readonly TimeSpan DefaultTimeout = TimeSpan.FromMinutes(2);
23: 
24:     private const long LargestSeconds = 4294967;
25: 
26:     /// <summary>
27:     /// The contract rows: each configured value and the timeout it must give. Unset, empty, not a number, zero,
28:     /// negative and larger than the timer's limit give the default; 1 to the limit, surrounding blanks allowed as
29:     /// before, give that many seconds.
30:     /// </summary>
31:     private static readonly (string? Configured, TimeSpan Expected)[] ContractRows =
32:     [
33:         (null, DefaultTimeout),
34:         (string.Empty, DefaultTimeout),
35:         ("   ", DefaultTimeout),
36:         ("not-a-number", DefaultTimeout),
37:         ("1.5", DefaultTimeout),
38:         ("0", DefaultTimeout),
39:         ("-1", DefaultTimeout),
40:         ("-2147483648", DefaultTimeout),
41:         ("1", TimeSpan.FromSeconds(1)),
42:         ("120", TimeSpan.FromSeconds(120)),
43:         (" 30 ", TimeSpan.FromSeconds(30)),
44:         ("4294966", TimeSpan.FromSeconds(4294966)),
45:         ("4294967", TimeSpan.FromSeconds(LargestSeconds)),
46:         ("4294968", DefaultTimeout),
47:         ("2147483647", DefaultTimeout),
48:         ("99999999999", DefaultTimeout),
49:     ];
50: 
51:     /// <summary>
52:     /// Asserts that <paramref name="parse"/> gives the expected timeout for every contract row, and that every timeout
53:     /// it gives is accepted by <see cref="CancellationTokenSource.CancelAfter(TimeSpan)"/>.
54:     /// </summary>
55:     /// <param name="parse">The parse function under test.</param>
56:     internal static void AssertParseContract(Func<string?, TimeSpan> parse)
57:     {
58:         ArgumentNullException.ThrowIfNull(parse);
59:         var wrong = new List<string>();
60:         foreach (var (configured, expected) in ContractRows)
61:         {
62:             var actual = parse(configured);
63:             if (actual != expected)
64:             {
65:                 wrong.Add($"'{configured ?? "(unset)"}' gave {actual} instead of {expected}");
66:                 continue;
67:             }
68: 
69:             using var source = new CancellationTokenSource();
70:             source.CancelAfter(actual);
71:         }
72: 
73:         Assert.Empty(wrong);
74:     }
75: 
76:     /// <summary>Runtime check: the cancellation timer accepts the largest whole-second delay and rejects one more.</summary>
77:     [Fact]
78:     public void CancelAfter_AcceptsTheLargestSecondsAndRejectsOneMore()
79:     {
80:         using var source = new CancellationTokenSource();
81:         source.CancelAfter(TimeSpan.FromSeconds(LargestSeconds));
82:         Assert.Throws<ArgumentOutOfRangeException>(() => source.CancelAfter(TimeSpan.FromSeconds(LargestSeconds + 1L)));
83:     }
84: 
85:     /// <summary>
86:     /// Binding: the production parser, <see cref="ReplCommandTimeout.Parse"/>, satisfies the same contract rows the
87:     /// scripted reference passed and the wrong parsers failed, and its default and limit are the contract's.
88:     /// </summary>
89:     [Fact]
90:     public void ProductionParser_SatisfiesTheContract()
91:     {
92:         Assert.Equal(DefaultTimeout, ReplCommandTimeout.Default);
93:         Assert.Equal(LargestSeconds, ReplCommandTimeout.LargestSeconds);
94:         AssertParseContract(ReplCommandTimeout.Parse);
95:     }
96: 
97:     /// <summary>Mock gate positive control: the scripted reference parser satisfies every contract row.</summary>
98:     [Fact]
99:     public void ScriptedReferenceParser_SatisfiesTheContract() =>
100:         AssertParseContract(ScriptedReference);
101: 
102:     /// <summary>
103:     /// Mock gate negative controls, each rejected inside a passing harness: the parser before this fix (no upper bound,
104:     /// so 4294968 and 2147483647 pass through), one that caps a larger value at the limit instead of using the default,
105:     /// one that refuses the limit itself, and one that refuses 1.
106:     /// </summary>
107:     [Fact]
108:     public void WrongParsers_AreRejectedInsidePassingHarness()
109:     {
110:         Assert.NotNull(Record.Exception(() => AssertParseContract(Unbounded)));
111:         Assert.NotNull(Record.Exception(() => AssertParseContract(Capping)));
112:         Assert.NotNull(Record.Exception(() => AssertParseContract(configured => Bounded(configured, 1, LargestSeconds - 1))));
113:         Assert.NotNull(Record.Exception(() => AssertParseContract(configured => Bounded(configured, 2, LargestSeconds))));
114:     }
115: 
116:     /// <summary>The scripted reference parse, also used by <see cref="ReplCommandTimeoutCallSiteTests"/>.</summary>
117:     internal static TimeSpan ScriptedReference(string? configured) => Bounded(configured, 1, LargestSeconds);
118: 
119:     private static TimeSpan Bounded(string? configured, long smallest, long largest) =>
120:         long.TryParse(configured, NumberStyles.Integer, CultureInfo.InvariantCulture, out var seconds) && seconds >= smallest && seconds <= largest
121:             ? TimeSpan.FromSeconds(seconds)
122:             : DefaultTimeout;
123: 
124:     /// <summary>The parse from before the R7-F1 fix, a negative control here and in <see cref="ReplCommandTimeoutCallSiteTests"/>.</summary>
125:     internal static TimeSpan Unbounded(string? configured) =>
126:         int.TryParse(configured, out var seconds) && seconds > 0 ? TimeSpan.FromSeconds(seconds) : DefaultTimeout;
127: 
128:     private static TimeSpan Capping(string? configured) =>
129:         long.TryParse(configured, NumberStyles.Integer, CultureInfo.InvariantCulture, out var seconds) && seconds > 0
130:             ? TimeSpan.FromSeconds(Math.Min(seconds, LargestSeconds))
131:             : DefaultTimeout;
132: }
