166:     private static async Task<string> RunReplAsync(ReplProcess repl, string requestId, string yaml)
167:     {
168:         await repl.WriteLineAsync(yaml).ConfigureAwait(true);
169:         var received = await repl.WaitForResponseAsync(requestId, ReplRequestTimeout).ConfigureAwait(true);
170:         Assert.True(received, $"Timed out waiting for REPL response '{requestId}'.{Environment.NewLine}{repl.Diagnostics}");
171: 
172:         var document = repl.GetResponseDocument(requestId);
173:         Assert.False(string.IsNullOrWhiteSpace(document), $"Missing REPL document for '{requestId}'.{Environment.NewLine}{repl.Diagnostics}");
174:         Assert.True(
175:             document.Contains("type: result", StringComparison.Ordinal),
176:             $"Expected a result envelope for '{requestId}' but received:{Environment.NewLine}{document}");
177:         return document;
178:     }
