177:     private static string SanitizeAgentKey(string value)
178:     {
179:         var builder = new StringBuilder(value.Length);
180:         var lastWasSeparator = false;
181:         foreach (var ch in value)
182:         {
183:             if (char.IsAsciiLetterOrDigit(ch))
184:             {
185:                 builder.Append(ch);
186:                 lastWasSeparator = false;
187:             }
188:             else if (!lastWasSeparator)
189:             {
190:                 builder.Append('-');
191:                 lastWasSeparator = true;
192:             }
193:         }
194: 
195:         var sanitized = builder.ToString().Trim('-');
196:         return string.IsNullOrWhiteSpace(sanitized) ? "default" : sanitized;
197:     }
