16:     /// <summary>
17:     /// Adds the configured <see cref="McpDbContext"/> registration for the selected provider.
18:     /// </summary>
19:     /// <param name="services">Service collection receiving the DbContext registration.</param>
20:     /// <param name="configuration">Application configuration.</param>
21:     /// <param name="instanceName">Optional MCP instance name.</param>
22:     /// <param name="isTestEnvironment">Whether the current host environment is <c>Test</c>.</param>
23:     public static void AddConfiguredMcpDbContext(
24:         this IServiceCollection services,
25:         IConfiguration configuration,
26:         string? instanceName,
27:         bool isTestEnvironment)
28:     {
29:         ArgumentNullException.ThrowIfNull(services);
30:         ArgumentNullException.ThrowIfNull(configuration);
31: 
32:         if (isTestEnvironment && ShouldUseInMemoryDatabase(configuration, instanceName))
33:         {
34:             services.AddDbContext<McpDbContext>(options =>
35:             {
36:                 options.UseInMemoryDatabase(InMemoryDatabaseName);
37:                 options.EnableSensitiveDataLogging();
38:             }, ServiceLifetime.Scoped, ServiceLifetime.Scoped);
39:             return;
40:         }
41: 
42:         var runtimeOptions = ResolveRuntimeOptions(configuration, instanceName);
43:         var providerOptions = runtimeOptions.ProviderOptions;
44:         services.AddSingleton(runtimeOptions);
45:         services.AddSingleton(providerOptions);
46:         services.AddDbContext<McpDbContext>(options =>
47:         {
48:             McpDatabaseProviderFactory.Configure(options, providerOptions);
49:         }, ServiceLifetime.Scoped, ServiceLifetime.Scoped);
50:     }
