56:     /// <param name="instanceName">Optional MCP instance name.</param>
57:     /// <returns>The resolved provider options.</returns>
58:     public static McpDatabaseProviderOptions ResolveProviderOptions(IConfiguration configuration, string? instanceName)
59:         => ResolveRuntimeOptions(configuration, instanceName).ProviderOptions;
60: 
61:     /// <summary>
62:     /// Resolves the configured provider, connection string, and native encryption settings into one runtime contract.
63:     /// </summary>
