66:     /// <returns>The resolved runtime options.</returns>
67:     public static McpDatabaseRuntimeOptions ResolveRuntimeOptions(IConfiguration configuration, string? instanceName)
68:     {
69:         ArgumentNullException.ThrowIfNull(configuration);
70: 
71:         var requestedProvider = ResolveRequestedProvider(configuration, instanceName);
72:         var strategy = McpDatabaseProviderFactory.ResolveStrategy(requestedProvider);
73:         var migrationsAssembly = GetEffectiveDatabaseValue(configuration, instanceName, "MigrationsAssembly")
74:             ?? McpInstanceResolver.GetEffectiveMcpValue(configuration, instanceName, "DatabaseMigrationsAssembly")
75:             ?? QBrainAi.Common.AgentCli.ProductEnvironment.GetLegacy("MCP_DATABASE_MIGRATIONS_ASSEMBLY");
76: 
77:         var connectionString = strategy.Kind switch
78:         {
79:             McpDatabaseProviderKind.Sqlite => ResolveSqliteConnectionString(configuration, instanceName),
80:             McpDatabaseProviderKind.PostgreSql => ResolvePostgreSqlConnectionString(configuration, instanceName),
81:             McpDatabaseProviderKind.SqlServer => ResolveSqlServerConnectionString(configuration, instanceName),
82:             _ => throw new InvalidOperationException($"Unsupported MCP database provider '{requestedProvider}'."),
83:         };
84: 
85:         var autoMigrateRaw = GetEffectiveDatabaseValue(configuration, instanceName, "AutoMigrate");
86:         if (autoMigrateRaw is not null && !bool.TryParse(autoMigrateRaw, out _))
87:             throw new InvalidOperationException("Mcp:Database:AutoMigrate must be true or false.");
88:         var autoMigrate = autoMigrateRaw is null || bool.Parse(autoMigrateRaw);
89: 
90:         return new McpDatabaseRuntimeOptions(
91:             McpDatabaseProviderFactory.CreateOptions(requestedProvider, connectionString, migrationsAssembly),
92:             ResolveEncryptionOptions(configuration, instanceName),
93:             autoMigrate);
