192:             GetEffectiveDatabaseValue(configuration, instanceName, "Encryption:SqlServer:CertificateName")
193:                 ?? QBrainAi.Common.AgentCli.ProductEnvironment.GetLegacy("MCP_SQLSERVER_TDE_CERTIFICATE"),
