3: /// <summary>
4: /// TR-MCP-QBRAIN-005: Reads product environment variables with 1.x alias precedence.
5: /// QBRAINAI_* wins when set. The matching MCP_* variable is used when the new name is unset.
6: /// MCP_UNTRUSTED stays a literal sentinel and is not aliased.
7: /// </summary>
8: public static class ProductEnvironment
9: {
10:     /// <summary>The trust-failure sentinel. This literal does not change through 1.x.</summary>
11:     public const string UntrustedSentinel = "MCP_UNTRUSTED";
12: 
13:     /// <summary>
14:     /// Reads a legacy MCP_* variable, preferring QBRAINAI_* with the same suffix.
15:     /// </summary>
16:     /// <param name="legacyName">The existing variable name, including the MCP_ prefix.</param>
17:     /// <returns>The winning value, or null when neither variable is set.</returns>
18:     public static string? GetLegacy(string legacyName)
19:     {
20:         ArgumentException.ThrowIfNullOrWhiteSpace(legacyName);
21:         if (string.Equals(legacyName, UntrustedSentinel, StringComparison.Ordinal))
22:             return Environment.GetEnvironmentVariable(UntrustedSentinel);
23: 
24:         if (legacyName.StartsWith("MCP_", StringComparison.Ordinal))
25:         {
26:             var modernName = "QBRAINAI_" + legacyName["MCP_".Length..];
27:             var modern = Environment.GetEnvironmentVariable(modernName);
28:             if (!string.IsNullOrWhiteSpace(modern))
29:                 return modern;
30:         }
31: 
32:         return Environment.GetEnvironmentVariable(legacyName);
33:     }
34: }
