1: using QBrainAi.Repl.Host;
2: 
3: namespace QBrainAi.Repl.Core.Tests.Host;
4: 
5: /// <summary>
6: /// TR-MCP-REPL-008 (AC-1 to AC-4): Contract cases and assertions for the marker walk and its diagnostics, one named
7: /// case per criterion. The expected values come from the criteria: the walk goes from the start folder up to the file
8: /// system root, the nearest marker on the way up wins, walking up to a parent workspace is intended, and a walk that
9: /// finds nothing lists every folder it searched in walk order. Every case runs over an in-memory file system rooted at
10: /// the root of the host's temporary folder path (only the path string is used; no folder is read), so no case depends
11: /// on what the host holds. The same assertions run against a scripted walk (BDPv4 mock gate), wrong walks (negative
12: /// controls), and the production resolver.
13: /// </summary>
14: internal static class MarkerWalkContract
15: {
16:     /// <summary>The marker file name the walk looks for.</summary>
17:     internal const string MarkerFileName = "AGENTS-README-FIRST.yaml";
18: 
19:     /// <summary>The file system root of the scripted tree.</summary>
20:     internal static readonly string Root = Path.GetPathRoot(Path.GetTempPath())!;
21: 
22:     /// <summary>The scripted workspace folder under the root.</summary>
23:     internal static readonly string Workspace = Path.Combine(Root, "w");
24: 
25:     /// <summary>The scripted source folder under the workspace.</summary>
26:     internal static readonly string Source = Path.Combine(Workspace, "src");
27: 
28:     /// <summary>The folder every case starts its walk from.</summary>
29:     internal static readonly string Start = Path.Combine(Source, "nested");
30: 
31:     /// <summary>A marker walk: the marker found from <paramref name="startPath"/>, or null, and the folders searched.</summary>
32:     internal delegate string? Walk(string startPath, IMarkerFileSystem fileSystem, out IReadOnlyList<string> searched);
33: 
34:     /// <summary>A diagnosed resolution: whether it succeeded and, when it did not, its error.</summary>
35:     internal delegate bool Diagnose(string startPath, IMarkerFileSystem fileSystem, out string error);
36: 
37:     /// <summary>
38:     /// AC-1 FindMarkerFile_NoMarkerOnTheWayUp_ListsEveryFolderToTheRoot: no marker anywhere, so no marker is returned
39:     /// and the searched folders are the start, its parents, and the root, in that order.
40:     /// </summary>
41:     internal static void AssertNoMarkerOnTheWayUp(Walk walk)
42:     {
43:         var marker = walk(Start, new InMemoryMarkerFileSystem(), out var searched);
44: 
45:         Assert.Null(marker);
46:         Assert.Equal([Start, Source, Workspace, Root], searched);
47:     }
48: 
49:     /// <summary>
50:     /// AC-2 FindMarkerFile_MarkerInParent_IsFound: a marker only in the workspace folder is found, as intended, and the
51:     /// walk stops there.
52:     /// </summary>
53:     internal static void AssertMarkerInParentIsFound(Walk walk)
54:     {
55:         var marker = walk(Start, new InMemoryMarkerFileSystem(Workspace), out var searched);
56: 
57:         Assert.Equal(Path.Combine(Workspace, MarkerFileName), marker);
58:         Assert.Equal([Start, Source, Workspace], searched);
59:     }
60: 
61:     /// <summary>
62:     /// AC-3 FindMarkerFile_MarkersInStartAndParent_NearestWins: with markers in the start folder and the workspace
63:     /// folder, the start folder's marker is returned and only the start folder is searched.
64:     /// </summary>
65:     internal static void AssertNearestMarkerWins(Walk walk)
66:     {
67:         var marker = walk(Start, new InMemoryMarkerFileSystem(Start, Workspace), out var searched);
68: 
69:         Assert.Equal(Path.Combine(Start, MarkerFileName), marker);
70:         Assert.Equal([Start], searched);
71:     }
72: 
73:     /// <summary>
74:     /// AC-4 TryResolveWithDiagnostics_NoMarkerOnTheWayUp_NamesEveryFolderSearched: with no marker anywhere the
75:     /// resolution fails, and its error names the marker file and every folder searched.
76:     /// </summary>
77:     internal static void AssertDiagnosticsNameEveryFolder(Diagnose diagnose)
78:     {
79:         var ok = diagnose(Start, new InMemoryMarkerFileSystem(), out var error);
80: 
81:         Assert.False(ok);
82:         Assert.Contains(MarkerFileName, error, StringComparison.Ordinal);
83:         foreach (var folder in new[] { Start, Source, Workspace, Root })
84:             Assert.Contains(folder, error, StringComparison.Ordinal);
85:     }
86: 
87:     /// <summary>Asserts the three walk cases (AC-1 to AC-3) against <paramref name="walk"/>.</summary>
88:     internal static void AssertWalk(Walk walk)
89:     {
90:         AssertNoMarkerOnTheWayUp(walk);
91:         AssertMarkerInParentIsFound(walk);
92:         AssertNearestMarkerWins(walk);
93:     }
94: 
95:     /// <summary>An in-memory file system holding a marker in each named folder and nothing else.</summary>
96:     internal sealed class InMemoryMarkerFileSystem(params string[] markerFolders) : IMarkerFileSystem
97:     {
98:         /// <inheritdoc />
99:         public bool FileExists(string path)
100:             => markerFolders.Any(folder => string.Equals(Path.Combine(folder, MarkerFileName), path, StringComparison.Ordinal));
101: 
102:         /// <inheritdoc />
103:         public string[] ReadAllLines(string path)
104:             => throw new FileNotFoundException("The in-memory file system holds marker presence only; no case reads a marker.", path);
105:     }
106: }
