90:     private static MarkerWalkContract.Walk ScriptedWalk(WalkFault fault)
91:         => (string startPath, IMarkerFileSystem fileSystem, out IReadOnlyList<string> searched) =>
92:         {
93:             var folders = new List<string>();
94:             string? found = null;
95:             var current = new DirectoryInfo(startPath);
96:             if (fault == WalkFault.SkipsStart)
97:                 current = current.Parent;
98:             while (current is not null)
99:             {
100:                 if (fault == WalkFault.StopsBeforeRoot && current.Parent is null)
101:                     break;
102:                 folders.Add(current.FullName);
103:                 var candidate = Path.Combine(current.FullName, MarkerWalkContract.MarkerFileName);
104:                 if (fileSystem.FileExists(candidate))
105:                 {
106:                     found = candidate;
107:                     if (fault != WalkFault.FarthestWins)
108:                         break;
109:                 }
110: 
111:                 if (fault == WalkFault.StartOnly)
112:                     break;
113:                 current = current.Parent;
114:             }
115: 
116:             if (fault == WalkFault.ReversedOrder)
117:                 folders.Reverse();
118:             searched = folders;
119:             return found;
120:         };
121: 
122:     private static MarkerWalkContract.Diagnose ScriptedDiagnosis(DiagnosisFault fault)
123:         => (string startPath, IMarkerFileSystem fileSystem, out string error) =>
124:         {
125:             var marker = ScriptedWalk(WalkFault.None)(startPath, fileSystem, out var searched);
126:             if (marker is not null || fault == DiagnosisFault.ReportsSuccess)
127:             {
128:                 error = string.Empty;
129:                 return true;
130:             }
131: 
132:             var name = fault == DiagnosisFault.OmitsMarkerName ? "the marker file" : $"'{MarkerWalkContract.MarkerFileName}'";
133:             var list = fault == DiagnosisFault.OmitsSearchedFolders ? "the workspace folders" : string.Join("; ", searched);
134:             error = $"Marker file {name} not found. Searched: {list}.";
135:             return false;
136:         };
137: }
