83:     private static string SanitizeAgentKey(string agent)
84:     {
85:         var builder = new StringBuilder(agent.Length);
86:         var lastWasSeparator = false;
87:         foreach (var ch in agent)
88:         {
89:             if (char.IsAsciiLetterOrDigit(ch))
90:             {
91:                 builder.Append(ch);
92:                 lastWasSeparator = false;
93:             }
94:             else if (!lastWasSeparator && builder.Length > 0)
95:             {
96:                 builder.Append('-');
97:                 lastWasSeparator = true;
98:             }
99:         }
100: 
101:         return builder.ToString().Trim('-') is { Length: > 0 } key ? key : "default";
102:     }
