10: /// </summary>
11: /// <remarks>
12: /// Requirement coverage: TR-MCP-USECASE-019 AC-008 as replaced 2026-10-26T14:18:23 ("A test fixture that needs a
13: /// directory junction or link creates it with an operating-system call made in the test process"; operator: "Fix
14: /// flake, strengthen AC (Recommended)"; triage-report-8c2c30ef63d442bdb29fd785ec91e7d7). Test data: the documented
15: /// REPARSE_DATA_BUFFER layout for IO_REPARSE_TAG_MOUNT_POINT (tag 0xA0000003; ReparseDataLength; Reserved;
16: /// SubstituteNameOffset, SubstituteNameLength, PrintNameOffset, PrintNameLength; then the UTF-16 substitute name
17: /// "\??\" plus the target, a null, the print name, a null), pinned as literal bytes for one target and decoded field
18: /// by field for another, run against a builder passed in, so the contract is proved on a scripted reference builder
19: /// with negative controls before the fixture's builder exists. The checks are pure byte comparisons on every host and
20: /// touch no file system or environment, so they are unit tests.
21: /// </remarks>
22: public sealed class WindowsJunctionTests
23: {
24:     private const uint MountPointTag = 0xA0000003;
25: 
26:     /// <summary>The documented buffer for the target C:\a, byte by byte.</summary>
27:     private static readonly byte[] PinnedBufferForCDriveA =
28:     [
29:         0x03, 0x00, 0x00, 0xA0, // ReparseTag 0xA0000003
30:         0x24, 0x00, // ReparseDataLength 36
31:         0x00, 0x00, // Reserved
32:         0x00, 0x00, // SubstituteNameOffset 0
33:         0x10, 0x00, // SubstituteNameLength 16
34:         0x12, 0x00, // PrintNameOffset 18
35:         0x08, 0x00, // PrintNameLength 8
36:         0x5C, 0x00, 0x3F, 0x00, 0x3F, 0x00, 0x5C, 0x00, 0x43, 0x00, 0x3A, 0x00, 0x5C, 0x00, 0x61, 0x00, // \??\C:\a
37:         0x00, 0x00, // null
38:         0x43, 0x00, 0x3A, 0x00, 0x5C, 0x00, 0x61, 0x00, // C:\a
39:         0x00, 0x00, // null
40:     ];
41: 
42:     /// <summary>
43:     /// Asserts that <paramref name="build"/> gives the pinned bytes for C:\a and, for a longer target with a space,
44:     /// a buffer whose fields decode to the documented layout.
45:     /// </summary>
46:     /// <param name="build">The buffer builder under test.</param>
47:     internal static void AssertBufferContract(Func<string, byte[]> build)
48:     {
49:         ArgumentNullException.ThrowIfNull(build);
50:         Assert.Equal(PinnedBufferForCDriveA, build(@"C:\a"));
51: 
52:         const string target = @"D:\Temp\mcp twelfth external";
53:         var buffer = build(target);
54:         var substitute = @"\??\" + target;
55:         Assert.Equal(MountPointTag, BinaryPrimitives.ReadUInt32LittleEndian(buffer.AsSpan(0, 4)));
56:         Assert.Equal(buffer.Length - 8, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(4, 2)));
57:         Assert.Equal(0, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(6, 2)));
58:         Assert.Equal(0, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(8, 2)));
59:         Assert.Equal(substitute.Length * 2, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(10, 2)));
60:         Assert.Equal((substitute.Length * 2) + 2, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(12, 2)));
61:         Assert.Equal(target.Length * 2, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(14, 2)));
62:         Assert.Equal(substitute, Encoding.Unicode.GetString(buffer, 16, substitute.Length * 2));
63:         Assert.Equal(0, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(16 + (substitute.Length * 2), 2)));
64:         Assert.Equal(target, Encoding.Unicode.GetString(buffer, 16 + (substitute.Length * 2) + 2, target.Length * 2));
65:         Assert.Equal(0, BinaryPrimitives.ReadUInt16LittleEndian(buffer.AsSpan(buffer.Length - 2, 2)));
66:         Assert.Equal(16 + (substitute.Length * 2) + 2 + (target.Length * 2) + 2, buffer.Length);
67:     }
