69:     /// <summary>
70:     /// Binding: the fixture's builder, <see cref="WindowsJunction.BuildMountPointBuffer"/>, satisfies the same
71:     /// contract the scripted reference passed and the wrong builders failed, and its tag is the documented one.
72:     /// </summary>
73:     [Fact]
74:     public void FixtureBuilder_SatisfiesTheContract()
75:     {
76:         Assert.Equal(MountPointTag, WindowsJunction.MountPointTag);
77:         AssertBufferContract(WindowsJunction.BuildMountPointBuffer);
78:     }
79: 
80:     /// <summary>Mock gate positive control: the scripted reference builder satisfies the contract.</summary>
81:     [Fact]
82:     public void ScriptedReferenceBuilder_SatisfiesTheContract() =>
83:         AssertBufferContract(target => Scripted(target, MountPointTag, @"\??\", nullGap: true, headerInLength: false));
84: 
85:     /// <summary>
86:     /// Mock gate negative controls, each rejected inside a passing harness: the symbolic-link tag instead of the
87:     /// mount-point tag, a substitute name without the \??\ prefix, a print name that starts without the null after the
88:     /// substitute name, and a data length that also counts the 8-byte header.
89:     /// </summary>
90:     [Fact]
91:     public void WrongBuilders_AreRejectedInsidePassingHarness()
92:     {
93:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, 0xA000000C, @"\??\", nullGap: true, headerInLength: false))));
94:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, MountPointTag, string.Empty, nullGap: true, headerInLength: false))));
95:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, MountPointTag, @"\??\", nullGap: false, headerInLength: false))));
96:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, MountPointTag, @"\??\", nullGap: true, headerInLength: true))));
97:     }
