6: /// <summary>
7: /// Tests the shared CLI temporary-folder variable support of <see cref="CliTempVariables"/>: its name list matches the
8: /// four strategies' fallback chains, and its snapshot assertions accept a run that pointed the primary name at the test
9: /// folder, every other name at a separate fallback folder, and restored every name, and reject one that missed or
10: /// mis-set a name.
11: /// </summary>
12: /// <remarks>
13: /// Requirement coverage: TR-MCP-USECASE-018 AC-006 and TR-MCP-USECASE-019 AC-008 as amended 2026-10-26 ("set and
14: /// restore every variable their assertions or the code they call depend on, every name of a fallback chain the code
15: /// reads"; operator: "Strengthen AC, move 14 (Recommended)" and "Dependence + proof AC (Recommended)"; hostile
16: /// validation finding R6-F1). Test data: scripted snapshots (dictionaries of name to value); these mock gate controls
17: /// read and write no process environment, so they are unit tests. The class runs in
18: /// <see cref="ProcessEnvironmentCollection"/> because its binding tests write the process environment; those are
19: /// integration tests.
20: /// </remarks>
21: [Collection(ProcessEnvironmentCollection.Name)]
22: public sealed class CliTempVariablesTests
23: {
24:     private const string Folder = "/scripted/cli-temp-folder";
25: 
26:     private const string Fallback = "/scripted/cli-temp-fallback";
27: 
28:     /// <summary>
29:     /// The name list holds the five chain names once each: CliBrainSlotChatClient (QUADBRAIN_CLI, ONESHOT), Codex
30:     /// (CODEX_ONESHOT, CODEX_TRIAGE), one-shot (ONESHOT, CODEX_ONESHOT, CODEX_TRIAGE) and Grok (GROK_ONESHOT, ONESHOT).
31:     /// </summary>
32:     [Fact]
33:     public void Names_HoldEveryChainNameOnce()
34:     {
35:         string[] expected =
36:         [
37:             "MCPSERVER_CODEX_ONESHOT_TEMP",
38:             "MCPSERVER_CODEX_TRIAGE_TEMP",
39:             "MCPSERVER_GROK_ONESHOT_TEMP",
40:             "MCPSERVER_ONESHOT_TEMP",
41:             "MCPSERVER_QUADBRAIN_CLI_TEMP",
42:         ];
43: 
44:         Assert.Equal(expected, Names.Order(StringComparer.Ordinal));
45:     }
46: 
47:     /// <summary>
48:     /// Mock gate positive control: a scripted snapshot with the primary name at the folder and every other name at the
49:     /// fallback folder passes, for each name as the primary.
50:     /// </summary>
51:     /// <param name="primaryName">The name read first.</param>
52:     [Theory]
53:     [InlineData("MCPSERVER_QUADBRAIN_CLI_TEMP")]
54:     [InlineData("MCPSERVER_ONESHOT_TEMP")]
55:     [InlineData("MCPSERVER_CODEX_ONESHOT_TEMP")]
56:     public void ScriptedChain_PrimaryAtFolderOthersAtFallback_Passes(string primaryName) =>
57:         AssertChainAt(Scripted(name => name == primaryName ? Folder : Fallback), primaryName, Folder, Fallback);
58: 
59:     /// <summary>
60:     /// Mock gate negative controls: the primary name at the fallback folder, another name at the primary folder, a
61:     /// missing name, an unset name, a fallback folder equal to the primary folder, and a primary name outside the
62:     /// chain are each rejected, inside a passing harness.
63:     /// </summary>
64:     [Fact]
65:     public void ScriptedChain_WrongSnapshot_IsRejectedInsidePassingHarness()
66:     {
67:         const string primary = "MCPSERVER_QUADBRAIN_CLI_TEMP";
68:         var good = Scripted(name => name == primary ? Folder : Fallback);
69:         var primaryAtFallback = Scripted(_ => Fallback);
70:         var otherAtFolder = Scripted(name => name == primary || name == "MCPSERVER_ONESHOT_TEMP" ? Folder : Fallback);
71:         var missing = Scripted(name => name == primary ? Folder : Fallback);
72:         missing.Remove("MCPSERVER_GROK_ONESHOT_TEMP");
73:         var unset = Scripted(name => name == primary ? Folder : name == "MCPSERVER_CODEX_TRIAGE_TEMP" ? null : Fallback);
74:         var sameFolders = Scripted(_ => Folder);
75: 
76:         Assert.NotNull(Record.Exception(() => AssertChainAt(primaryAtFallback, primary, Folder, Fallback)));
77:         Assert.NotNull(Record.Exception(() => AssertChainAt(otherAtFolder, primary, Folder, Fallback)));
78:         Assert.NotNull(Record.Exception(() => AssertChainAt(missing, primary, Folder, Fallback)));
79:         Assert.NotNull(Record.Exception(() => AssertChainAt(unset, primary, Folder, Fallback)));
80:         Assert.NotNull(Record.Exception(() => AssertChainAt(sameFolders, primary, Folder, Folder)));
81:         Assert.NotNull(Record.Exception(() => AssertChainAt(good, "MCPSERVER_NOT_A_CHAIN_NAME", Folder, Fallback)));
82:     }
