97:         var leftSet = Scripted(name => name == "MCPSERVER_QUADBRAIN_CLI_TEMP" ? Folder : Prior(name));
98:         var newlySet = Scripted(name => name == "MCPSERVER_GROK_ONESHOT_TEMP" ? Folder : Prior(name));
99:         var missing = Scripted(Prior);
100:         missing.Remove("MCPSERVER_ONESHOT_TEMP");
101: 
102:         Assert.NotNull(Record.Exception(() => AssertRestored(before, leftSet)));
103:         Assert.NotNull(Record.Exception(() => AssertRestored(before, newlySet)));
104:         Assert.NotNull(Record.Exception(() => AssertRestored(before, missing)));
105:     }
