107:     /// <summary>
108:     /// Binding: for each name as the primary, the helper points that name at a new test folder and every other name at
109:     /// a separate new fallback folder, both under the official temporary folder, while the body runs, then restores
110:     /// every scripted earlier value (an unset name included) and deletes both folders. The test writes the process
111:     /// environment and restores the ambient values, so it is an integration test.
112:     /// </summary>
113:     /// <param name="primaryName">The name read first.</param>
114:     /// <returns>A task that completes when the assertions have run.</returns>
115:     [Theory]
116:     [Trait("Category", "Integration")]
117:     [InlineData("MCPSERVER_QUADBRAIN_CLI_TEMP")]
118:     [InlineData("MCPSERVER_ONESHOT_TEMP")]
119:     [InlineData("MCPSERVER_CODEX_ONESHOT_TEMP")]
120:     [InlineData("MCPSERVER_CODEX_TRIAGE_TEMP")]
121:     [InlineData("MCPSERVER_GROK_ONESHOT_TEMP")]
122:     public async Task RunWithTestFoldersAsync_PointsPrimaryAndFallbackThenRestoresThem(string primaryName)
123:     {
124:         var ambient = Snapshot();
125:         try
126:         {
127:             SetAll(Prior);
128:             var before = Snapshot();
129:             string? seenFolder = null;
130:             string? seenFallback = null;
131:             Dictionary<string, string?>? inside = null;
132:             var existed = false;
133: 
134:             await RunWithTestFoldersAsync(primaryName, (folder, fallbackFolder) =>
135:             {
136:                 seenFolder = folder;
137:                 seenFallback = fallbackFolder;
138:                 inside = Snapshot();
139:                 existed = Directory.Exists(folder) && Directory.Exists(fallbackFolder);
140:                 return Task.CompletedTask;
141:             }).ConfigureAwait(true);
142: 
143:             Assert.NotNull(seenFolder);
144:             Assert.NotNull(seenFallback);
145:             Assert.NotNull(inside);
146:             AssertChainAt(inside, primaryName, seenFolder, seenFallback);
147:             Assert.True(existed);
148:             var temp = Path.GetFullPath(Path.GetTempPath());
149:             Assert.StartsWith(temp, Path.GetFullPath(seenFolder), StringComparison.OrdinalIgnoreCase);
150:             Assert.StartsWith(temp, Path.GetFullPath(seenFallback), StringComparison.OrdinalIgnoreCase);
151:             Assert.False(Directory.Exists(seenFolder));
152:             Assert.False(Directory.Exists(seenFallback));
153:             AssertRestored(before, Snapshot());
154:         }
155:         finally
156:         {
157:             SetAll(name => ambient[name]);
158:         }
159:     }
160: 
161:     /// <summary>
162:     /// Binding: when the body throws, the exception reaches the caller and the helper still restores every scripted
163:     /// earlier value and deletes both folders. The test writes the process environment and restores the ambient
164:     /// values, so it is an integration test.
165:     /// </summary>
166:     /// <returns>A task that completes when the assertions have run.</returns>
167:     [Fact]
168:     [Trait("Category", "Integration")]
169:     public async Task RunWithTestFolderAsync_BodyThrows_StillRestoresAndDeletes()
170:     {
171:         var ambient = Snapshot();
172:         try
173:         {
174:             SetAll(Prior);
175:             var before = Snapshot();
176:             string? seenFolder = null;
177:             string? seenFallback = null;
178: 
179:             await Assert.ThrowsAsync<InvalidOperationException>(() => RunWithTestFoldersAsync("MCPSERVER_CODEX_ONESHOT_TEMP", (folder, fallbackFolder) =>
180:             {
181:                 seenFolder = folder;
182:                 seenFallback = fallbackFolder;
183:                 throw new InvalidOperationException("scripted body failure");
184:             })).ConfigureAwait(true);
185: 
186:             Assert.NotNull(seenFolder);
187:             Assert.NotNull(seenFallback);
188:             Assert.False(Directory.Exists(seenFolder));
189:             Assert.False(Directory.Exists(seenFallback));
190:             AssertRestored(before, Snapshot());
191:         }
192:         finally
193:         {
194:             SetAll(name => ambient[name]);
195:         }
196:     }
197: 
198:     /// <summary>
199:     /// Binding: a primary name outside the chain is refused before any variable is written or any folder is made.
200:     /// The test reads the process environment to prove nothing changed, so it is an integration test.
201:     /// </summary>
202:     /// <returns>A task that completes when the assertions have run.</returns>
203:     [Fact]
204:     [Trait("Category", "Integration")]
205:     public async Task RunWithTestFolderAsync_UnknownPrimary_IsRefusedWithoutChanges()
206:     {
207:         var before = Snapshot();
208:         var ran = false;
209: 
210:         await Assert.ThrowsAsync<ArgumentException>(() => RunWithTestFolderAsync("MCPSERVER_NOT_A_CHAIN_NAME", _ =>
211:         {
212:             ran = true;
213:             return Task.CompletedTask;
214:         })).ConfigureAwait(true);
215: 
216:         Assert.False(ran);
217:         AssertRestored(before, Snapshot());
218:     }
219: 
220:     private static void SetAll(Func<string, string?> value)
221:     {
222:         foreach (var name in Names)
223:             Environment.SetEnvironmentVariable(name, value(name));
224:     }
225: 
226:     private static string? Prior(string name) =>
227:         name == "MCPSERVER_GROK_ONESHOT_TEMP" ? null : "/scripted/prior/" + name;
228: 
229:     private static Dictionary<string, string?> Scripted(Func<string, string?> value) =>
230:         Names.ToDictionary(name => name, value, StringComparer.Ordinal);
231: }
