5: /// <summary>
6: /// TR-MCP-QUALITY / G1 provider diagnosis: proves <see cref="EphemeralPostgresFixture"/>
7: /// fail-closed initdb evidence captures sanitized invocation, stdout, and stderr.
8: /// </summary>
9: public sealed class EphemeralPostgresFixtureTests
10: {
11:     /// <summary>
12:     /// Overlay G1 leftover: when initdb exits non-zero, the fixture exception must retain
13:     /// sanitized executable path, arguments, cwd, exit code, stdout, and stderr. "initdb exited 1"
14:     /// alone is not sufficient. TEST-MCP-AIUNIT-002 adjacent provider diagnosis. When
15:     /// MCP_TEST_POSTGRES_CONNECTION names a server (the container endpoint; operator decision
16:     /// 2026-10-11 for BUG-BASELINE-005), the fixture provisions nothing locally and initdb never
17:     /// runs, so the test proves that adoption instead: the fixture uses that server and holds no
18:     /// local binaries or data directory. The comparison never prints the connection string.
19:     /// </summary>
20:     [Fact]
21:     [Trait("Category", "Integration")]
22:     public void EphemeralPostgresFixture_InitdbFailure_CapturesSanitizedInvocationStdoutAndStderr()
23:     {
24:         var external = Environment.GetEnvironmentVariable("MCP_TEST_POSTGRES_CONNECTION");
25:         if (!string.IsNullOrWhiteSpace(external))
26:         {
27:             using var fixture = new EphemeralPostgresFixture();
28:             Assert.True(
29:                 string.Equals(external, fixture.ServerConnectionString, StringComparison.Ordinal),
30:                 "The fixture did not adopt MCP_TEST_POSTGRES_CONNECTION.");
31:             Assert.Null(GetPrivateField(fixture, "_pgBin"));
32:             Assert.Null(GetPrivateField(fixture, "_dataDir"));
33:             return;
34:         }
35: 
36:         var find = typeof(EphemeralPostgresFixture).GetMethod(
37:             "FindPostgresBinaries",
38:             BindingFlags.NonPublic | BindingFlags.Static);
39:         Assert.NotNull(find);
40:         var pgBin = find!.Invoke(null, null) as string;
41:         Assert.False(
42:             string.IsNullOrWhiteSpace(pgBin),
43:             "PostgreSQL binaries not found. Run InstallTestDependencies or install PostgreSQL locally. Do not skip.");
44: 
45:         var initdb = Path.Combine(pgBin!, "initdb.exe");
46:         Assert.True(File.Exists(initdb), $"initdb.exe missing under {pgBin}");
47: 
48:         var runTool = typeof(EphemeralPostgresFixture).GetMethod(
49:             "RunTool",
50:             BindingFlags.NonPublic | BindingFlags.Static);
51:         Assert.NotNull(runTool);
52: 
53:         var exception = Assert.Throws<TargetInvocationException>(
54:             () => runTool!.Invoke(null, [initdb, "--this-flag-does-not-exist", true]));
55:         var inner = Assert.IsType<InvalidOperationException>(exception.InnerException);
56:         var message = inner.Message;
57: 
58:         Assert.Contains("exit code", message, StringComparison.OrdinalIgnoreCase);
59:         Assert.Contains("stdout", message, StringComparison.OrdinalIgnoreCase);
60:         Assert.Contains("stderr", message, StringComparison.OrdinalIgnoreCase);
61:         Assert.Contains("arguments", message, StringComparison.OrdinalIgnoreCase);
62:         Assert.Contains("cwd", message, StringComparison.OrdinalIgnoreCase);
63:         Assert.DoesNotContain(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), message, StringComparison.OrdinalIgnoreCase);
64:         Assert.Contains("initdb.exe", message, StringComparison.OrdinalIgnoreCase);
65:     }
66: 
67:     private static object? GetPrivateField(EphemeralPostgresFixture fixture, string name)
68:     {
69:         var field = typeof(EphemeralPostgresFixture).GetField(name, BindingFlags.NonPublic | BindingFlags.Instance);
70:         Assert.NotNull(field);
71:         return field!.GetValue(fixture);
72:     }
73: }
