297:     private async Task<MarkerSettings> WaitForMarkerAsync()
298:     {
299:         using var timeout = new CancellationTokenSource(MarkerTimeout);
300:         using var watcher = new FileSystemWatcher(WorkspacePath, MarkerFileService.MarkerFileName)
301:         {
302:             NotifyFilter = NotifyFilters.CreationTime
303:                 | NotifyFilters.FileName
304:                 | NotifyFilters.LastWrite
305:                 | NotifyFilters.Size,
306:         };
307:         var signal = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
308:         FileSystemEventHandler onChanged = (_, _) => signal.TrySetResult();
309:         RenamedEventHandler onRenamed = (_, _) => signal.TrySetResult();
310:         watcher.Created += onChanged;
311:         watcher.Changed += onChanged;
312:         watcher.Renamed += onRenamed;
313:         watcher.EnableRaisingEvents = true;
314: 
315:         while (!timeout.IsCancellationRequested)
316:         {
317:             if (TryReadMarker(out var marker))
318:             {
319:                 return marker!;
320:             }
321: 
322:             if (_process is { HasExited: true })
323:             {
324:                 // Drain the redirected output so the message and the restart check see all of it.
325:                 await _process.WaitForExitAsync().ConfigureAwait(false);
326:                 throw new InvalidOperationException(
327:                     $"QBrain.AI exited before generating '{MarkerPath}' with code {_process.ExitCode}.{Environment.NewLine}{Diagnostics}");
328:             }
329: 
330:             var delay = Task.Delay(TimeSpan.FromMilliseconds(250), timeout.Token);
331:             var completed = await Task.WhenAny(signal.Task, delay).ConfigureAwait(false);
332:             if (completed == signal.Task)
333:             {
334:                 signal = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
335:             }
336:         }
337: 
338:         throw new TimeoutException(
339:             $"Timed out after {MarkerTimeout} waiting for generated marker '{MarkerPath}'.{Environment.NewLine}{Diagnostics}");
340:     }
