342:     private bool TryReadMarker(out MarkerSettings? marker)
343:     {
344:         marker = null;
345:         if (!File.Exists(MarkerPath))
346:         {
347:             return false;
348:         }
349: 
350:         try
351:         {
352:             var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
353:             foreach (var rawLine in File.ReadLines(MarkerPath))
354:             {
355:                 var line = rawLine.Trim();
356:                 if (line.Length == 0 || line.StartsWith("#", StringComparison.Ordinal))
357:                 {
358:                     continue;
359:                 }
360: 
361:                 var separator = line.IndexOf(':', StringComparison.Ordinal);
362:                 if (separator <= 0)
363:                 {
364:                     continue;
365:                 }
366: 
367:                 var key = line[..separator].Trim();
368:                 if (key is not ("port" or "baseUrl" or "apiKey" or "workspacePath"))
369:                 {
370:                     continue;
371:                 }
372: 
373:                 values[key] = Unquote(line[(separator + 1)..].Trim());
374:             }
375: 
376:             if (!values.TryGetValue("port", out var rawPort)
377:                 || !int.TryParse(rawPort, NumberStyles.Integer, CultureInfo.InvariantCulture, out var port)
378:                 || !values.TryGetValue("baseUrl", out var baseUrl)
379:                 || string.IsNullOrWhiteSpace(baseUrl)
380:                 || !values.TryGetValue("apiKey", out var apiKey)
381:                 || string.IsNullOrWhiteSpace(apiKey))
382:             {
383:                 return false;
384:             }
385: 
386:             marker = new MarkerSettings(port, baseUrl.TrimEnd('/'), apiKey);
387:             return true;
388:         }
389:         catch (IOException)
390:         {
391:             return false;
392:         }
393:         catch (UnauthorizedAccessException)
394:         {
395:             return false;
396:         }
397:     }
