18:     internal const int ConnectTimeoutSeconds = 120;
19: 
20:     /// <summary>The built-in LocalDB default: integrated security, a trusted certificate, no database.</summary>
21:     internal static string LocalDbDefault { get; } = new SqlConnectionStringBuilder
22:     {
23:         DataSource = @"(localdb)\MSSQLLocalDB",
24:         IntegratedSecurity = true,
25:         TrustServerCertificate = true,
