631: function Get-ReplMethodTimeoutSeconds {
632:     # TR-MCP-REPL-012: per-method timeout. Long-running requirement/agent methods (which invoke
633:     # external CLIs and can take minutes) get an extended, env-configurable budget; everything else
634:     # keeps the short default so sessionlog calls fail fast (BUG-TRIAGE-072).
635:     param([Parameter(Mandatory)][string]$Method)
636: 
637:     $default = if ($env:REPL_TIMEOUT) { [int]$env:REPL_TIMEOUT } else { 30 }
638:     $long = if ($env:REPL_LONG_TIMEOUT) { [int]$env:REPL_LONG_TIMEOUT } else { 300 }
639:     $helper = if ($env:REPL_HELPER_TIMEOUT) { [int]$env:REPL_HELPER_TIMEOUT } else { 120 }
640: 
641:     if ($script:ReplFailsafeDraining -and $Method -eq 'client.SessionLog.SubmitAsync') {
642:         # TR-MCP-REPL-012 AC3 / TEST-MCP-195 AC5-7: drain SubmitAsync uses
643:         # REPL_FAILSAFE_DRAIN_TIMEOUT (default 120s), or REPL_TIMEOUT when greater.
644:         # Sessionlog workflow methods keep $default (30s). Nested drain stays deferred.
645:         $drain = if ($env:REPL_FAILSAFE_DRAIN_TIMEOUT) { [int]$env:REPL_FAILSAFE_DRAIN_TIMEOUT } else { 120 }
646:         $seconds = if ($default -gt $drain) { $default } else { $drain }
647:     } else {
648:         $seconds = switch -Wildcard ($Method) {
649:             'workflow.todo.analyzeRequirements'       { $long; break }
650:             'workflow.requirements.generateDocument'  { $long; break }
651:             'workflow.requirements.ingestDocument'    { $long; break }
652:             'workflow.requirements.analyze*'          { $long; break }
653:             'client.Requirements.Analyze*'            { $long; break }
654:             'workflow.agenthelp.submitTurn'           { $helper; break }
655:             default                                   { $default }
656:         }
657:     }
658: 
659:     # TR-MCP-REPL-012 AC-001 (D1, triage-report-124a374c): inside a hook no call
660:     # may wait past the hook's deadline; outside a hook the timeout is unchanged.
661:     return (Get-ReplCappedTimeout -TimeoutSeconds $seconds -RemainingMs (Get-ReplHookTimeLeft))
662: }
663: 
664: function Get-ReplHookTimeLeft {
665:     # TR-MCP-REPL-012 AC-001 (D1): milliseconds left before the deadline that
666:     # plugin-hook.ps1 publishes in MCP_HOOK_DEADLINE_UTC_MS (Unix milliseconds);
667:     # $null outside a hook. May be negative once the deadline has passed.
668:     $deadline = 0L
669:     if (-not [long]::TryParse([string]$env:MCP_HOOK_DEADLINE_UTC_MS, [ref]$deadline) -or $deadline -le 0) { return $null }
670:     return ($deadline - [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds())
671: }
672: 
673: function Get-ReplCappedTimeout {
674:     # TR-MCP-REPL-012 AC-001 (D1): the lesser of the per-method timeout and the
675:     # whole seconds left before the hook deadline, so a slow or silent server ends
676:     # the call in time and the persist falls back to its write-ahead failsafe
677:     # record. 0 when less than one second is left: the call is then not started
678:     # (Invoke-ReplRawCore), because a call begun after the deadline would carry the
679:     # hook past its budget. Without a deadline the timeout is unchanged.
680:     param(
681:         [Parameter(Mandatory)][int]$TimeoutSeconds,
682:         [AllowNull()][Nullable[long]]$RemainingMs
683:     )
684:     if ($null -eq $RemainingMs) { return $TimeoutSeconds }
685:     return [int][Math]::Max(0, [Math]::Min([double]$TimeoutSeconds, [Math]::Floor([double]$RemainingMs / 1000)))
686: }
687: 
688: function Invoke-ReplRaw {
689:     param(
690:         [Parameter(Mandatory)][string]$Method,
691:         [string]$ParamsYaml = ''
692:     )
693:     # TR-MCP-REPL-016 AC-001 (D1): a drain deferred by an earlier successful call no
694:     # longer runs here, ahead of this call: it ran before beginTurn's new-turn persist
695:     # and never ran at all in an invocation with one backend call. The script entry
696:     # runs it once the invoked method has completed.
697:     $script:ReplRawInFlight = $true
698:     try {
699:         return (Invoke-ReplRawCore -Method $Method -ParamsYaml $ParamsYaml)
700:     }
