90:         if (psi.Environment.Count == 0)
91:             return null;
92: 
93:         var result = new Dictionary<string, string>(psi.Environment.Count, StringComparer.OrdinalIgnoreCase);
94:         var currentEnvironment = Environment.GetEnvironmentVariables();
95:         foreach (var (key, value) in psi.Environment)
96:         {
97:             if (value is null)
98:                 continue;
99: 
100:             var currentValue = currentEnvironment[key] as string;
101:             if (!string.Equals(currentValue, value, StringComparison.Ordinal))
102:                 result[key] = value;
103:         }
104: 
105:         return result.Count > 0 ? result : null;
106:     }
