5: /// <summary>
6: /// TR-MCP-NUKE-019: Contract cases and assertions for <see cref="IProvisioningDownload"/>. The expected
7: /// behavior comes from the acceptance criterion: the body is written to the destination as it arrives, the download
8: /// has no limit on its total duration, and it fails naming the URL on an error status or when no data arrives for the
9: /// inactivity limit. Every case runs through a scripted <see cref="HttpMessageHandler"/> in memory (no network) and
10: /// writes under a temporary folder it removes. The same assertions run against the scripted download (BDPv4 mock
11: /// gate), wrong downloads (negative controls), and the production download.
12: /// </summary>
13: /// <remarks>
14: /// The timed cases keep wide margins so machine load cannot flip them: chunks arrive every 100 ms against a 1 s
15: /// inactivity limit, the steady transfer runs about 2.5 s (two and a half inactivity limits), and a download that does
16: /// not fail a stalled transfer is cut off by the harness after 10 s. The client check catches a client that keeps
17: /// HttpClient's default 100 s total limit, which no short transfer could reveal.
18: /// </remarks>
19: internal static class ProvisioningDownloadContract
20: {
21:     /// <summary>The URL every case downloads.</summary>
22:     internal static readonly Uri Url = new("https://downloads.example.test/provisioning/release-asset.bin");
23: 
24:     /// <summary>The inactivity limit every timed case passes.</summary>
25:     internal static readonly TimeSpan InactivityLimit = TimeSpan.FromSeconds(1);
26: 
27:     /// <summary>How long the harness waits for a stalled download to fail before it rejects the download.</summary>
28:     internal static readonly TimeSpan StallCutoff = TimeSpan.FromSeconds(10);
29: 
30:     /// <summary>Asserts every contract case against <paramref name="download"/>.</summary>
31:     /// <param name="download">Download under test.</param>
32:     internal static async Task AssertDownloadAsync(IProvisioningDownload download)
33:     {
34:         AssertClientHasNoTotalLimit(download);
35:         await AssertWritesAsItArrivesAsync(download).ConfigureAwait(true);
36:         await AssertSteadySlowTransferCompletesAsync(download).ConfigureAwait(true);
37:         await AssertStalledTransferFailsNamingUrlAsync(download).ConfigureAwait(true);
38:         await AssertErrorStatusFailsNamingUrlAsync(download).ConfigureAwait(true);
39:     }
40: 
41:     /// <summary>The client a download creates has no total time limit.</summary>
42:     internal static void AssertClientHasNoTotalLimit(IProvisioningDownload download)
43:     {
44:         using var handler = new ScriptedHandler(HttpStatusCode.OK, () => new ChunkStream(1, TimeSpan.Zero, null));
45:         using var client = download.CreateClient(handler);
46:         Assert.Equal(Timeout.InfiniteTimeSpan, client.Timeout);
47:     }
48: 
49:     /// <summary>Eight 64 KB chunks: the destination holds every byte, and part of it was on disk before the body ended.</summary>
50:     internal static async Task AssertWritesAsItArrivesAsync(IProvisioningDownload download)
51:     {
52:         using var folder = new TemporaryFolder();
53:         var destination = Path.Combine(folder.Path, "asset.bin");
54:         ChunkStream? stream = null;
55:         using var handler = new ScriptedHandler(HttpStatusCode.OK, () => stream = new ChunkStream(8, TimeSpan.Zero, destination));
56: 
57:         await AssertCompletesAsync(download, handler, destination).ConfigureAwait(true);
58: 
59:         Assert.NotNull(stream);
60:         Assert.Equal(ChunkStream.Expected(8), await File.ReadAllBytesAsync(destination).ConfigureAwait(true));
61:         Assert.True(stream!.SawPartialFileBeforeEnd, "The body was not written to the destination as it arrived.");
62:     }
63: 
64:     /// <summary>25 chunks 100 ms apart (about 2.5 inactivity limits in all) download to completion.</summary>
65:     internal static async Task AssertSteadySlowTransferCompletesAsync(IProvisioningDownload download)
66:     {
67:         using var folder = new TemporaryFolder();
68:         var destination = Path.Combine(folder.Path, "asset.bin");
69:         using var handler = new ScriptedHandler(HttpStatusCode.OK, () => new ChunkStream(25, TimeSpan.FromMilliseconds(100), null));
70: 
71:         await AssertCompletesAsync(download, handler, destination).ConfigureAwait(true);
72: 
73:         Assert.Equal(ChunkStream.Expected(25), await File.ReadAllBytesAsync(destination).ConfigureAwait(true));
74:     }
75: 
76:     /// <summary>A download that must complete: any exception it throws fails the contract with that exception's text.</summary>
77:     private static async Task AssertCompletesAsync(IProvisioningDownload download, HttpMessageHandler handler, string destination)
78:     {
79:         var failure = await Record.ExceptionAsync(
80:             () => download.DownloadAsync(handler, Url, destination, InactivityLimit, CancellationToken.None)).ConfigureAwait(true);
81:         Assert.True(failure is null, $"The download did not complete: {failure?.GetType().Name}: {failure?.Message}");
82:     }
83: 
84:     /// <summary>One chunk, then no data: the download fails within the cutoff with the URL in the message.</summary>
85:     internal static async Task AssertStalledTransferFailsNamingUrlAsync(IProvisioningDownload download)
86:     {
87:         using var folder = new TemporaryFolder();
88:         var destination = Path.Combine(folder.Path, "asset.bin");
89:         using var handler = new ScriptedHandler(HttpStatusCode.OK, () => new ChunkStream(1, TimeSpan.Zero, null, stallAfter: true));
90:         using var cutoff = new CancellationTokenSource(StallCutoff);
91: 
92:         var attempt = download.DownloadAsync(handler, Url, destination, InactivityLimit, cutoff.Token);
93:         var failure = await Record.ExceptionAsync(() => attempt).ConfigureAwait(true);
94: 
95:         Assert.NotNull(failure);
96:         Assert.False(cutoff.IsCancellationRequested, "A stalled transfer did not fail within the inactivity limit.");
97:         Assert.Contains(Url.ToString(), failure!.Message, StringComparison.Ordinal);
98:     }
99: 
100:     /// <summary>A 404 answer fails the download with the URL in the message.</summary>
101:     internal static async Task AssertErrorStatusFailsNamingUrlAsync(IProvisioningDownload download)
102:     {
103:         using var folder = new TemporaryFolder();
104:         var destination = Path.Combine(folder.Path, "asset.bin");
105:         using var handler = new ScriptedHandler(HttpStatusCode.NotFound, () => new ChunkStream(1, TimeSpan.Zero, null));
106: 
107:         var failure = await Record.ExceptionAsync(
108:             () => download.DownloadAsync(handler, Url, destination, InactivityLimit, CancellationToken.None)).ConfigureAwait(true);
109: 
110:         Assert.NotNull(failure);
111:         Assert.Contains(Url.ToString(), failure!.Message, StringComparison.Ordinal);
112:     }
