114:     /// <summary>Answers every request with the status and a fresh body stream.</summary>
115:     internal sealed class ScriptedHandler(HttpStatusCode status, Func<Stream> body) : HttpMessageHandler
116:     {
117:         /// <inheritdoc />
118:         protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
119:             => Task.FromResult(new HttpResponseMessage(status) { Content = new StreamContent(body()), RequestMessage = request });
120:     }
121: 
122:     /// <summary>
123:     /// A body of 64 KB chunks with an optional delay before each chunk and an optional stall after the last one. When
124:     /// given the destination path, it records whether the file already held data when a later chunk was read.
125:     /// </summary>
126:     internal sealed class ChunkStream(int chunks, TimeSpan delay, string? destination, bool stallAfter = false) : Stream
127:     {
128:         /// <summary>The size of each chunk.</summary>
129:         internal const int ChunkSize = 64 * 1024;
130: 
131:         private int _chunk;
132:         private int _offset;
133: 
134:         /// <summary>Gets whether the destination already held data when a later chunk was read.</summary>
135:         internal bool SawPartialFileBeforeEnd { get; private set; }
136: 
137:         /// <inheritdoc />
138:         public override bool CanRead => true;
139: 
140:         /// <inheritdoc />
141:         public override bool CanSeek => false;
142: 
143:         /// <inheritdoc />
144:         public override bool CanWrite => false;
145: 
146:         /// <inheritdoc />
147:         public override long Length => throw new NotSupportedException();
148: 
149:         /// <inheritdoc />
150:         public override long Position
151:         {
152:             get => throw new NotSupportedException();
153:             set => throw new NotSupportedException();
154:         }
155: 
156:         /// <summary>The bytes the body holds for <paramref name="chunks"/> chunks.</summary>
157:         internal static byte[] Expected(int chunks)
158:         {
159:             var bytes = new byte[chunks * ChunkSize];
160:             for (var i = 0; i < bytes.Length; i++)
161:                 bytes[i] = (byte)((i / ChunkSize) + 1);
162:             return bytes;
163:         }
164: 
165:         /// <inheritdoc />
166:         public override int Read(byte[] buffer, int offset, int count)
167:             => ReadAsync(buffer.AsMemory(offset, count)).AsTask().GetAwaiter().GetResult();
168: 
169:         /// <inheritdoc />
170:         public override async ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default)
171:         {
172:             if (_chunk >= chunks)
173:             {
174:                 if (stallAfter)
175:                     await Task.Delay(Timeout.Infinite, cancellationToken).ConfigureAwait(false);
176:                 return 0;
177:             }
178: 
179:             if (_offset == 0)
180:             {
181:                 if (_chunk >= 2 && destination is not null && File.Exists(destination) && new FileInfo(destination).Length > 0)
182:                     SawPartialFileBeforeEnd = true;
183:                 if (delay > TimeSpan.Zero)
184:                     await Task.Delay(delay, cancellationToken).ConfigureAwait(false);
185:             }
186: 
187:             var count = Math.Min(buffer.Length, ChunkSize - _offset);
188:             buffer.Span[..count].Fill((byte)(_chunk + 1));
189:             _offset += count;
190:             if (_offset == ChunkSize)
191:             {
192:                 _offset = 0;
193:                 _chunk++;
194:             }
195: 
196:             return count;
197:         }
198: 
199:         /// <inheritdoc />
200:         public override void Flush()
201:         {
202:         }
203: 
204:         /// <inheritdoc />
205:         public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
206: 
207:         /// <inheritdoc />
208:         public override void SetLength(long value) => throw new NotSupportedException();
209: 
210:         /// <inheritdoc />
211:         public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
212:     }
213: 
