215:     private sealed class TemporaryFolder : IDisposable
216:     {
217:         public TemporaryFolder()
218:         {
219:             Path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "provisioning-download-" + Guid.NewGuid().ToString("N"));
220:             Directory.CreateDirectory(Path);
221:         }
222: 
223:         public string Path { get; }
224: 
225:         public void Dispose()
226:         {
227:             if (Directory.Exists(Path))
228:                 Directory.Delete(Path, recursive: true);
229:         }
230:     }
