3: /// <summary>
4: /// TR-MCP-NUKE-019, BDPv4 mock gate: proves the <see cref="ProvisioningDownloadContract"/> assertions accept a
5: /// scripted download that streams to disk with no total limit and an inactivity limit, and reject deliberately wrong
6: /// downloads (negative controls), before any production download code is written. Every case runs in memory through
7: /// a scripted message handler; no network is used.
8: /// </summary>
9: public sealed class ProvisioningDownloadMockGateTests
10: {
11:     /// <summary>TR-MCP-NUKE-019: the scripted download passes every contract case.</summary>
12:     [Fact]
13:     public async Task ScriptedDownload_PassesContract()
14:         => await ProvisioningDownloadContract.AssertDownloadAsync(new ScriptedDownload(Fault.None)).ConfigureAwait(true);
15: 
16:     /// <summary>
17:     /// TR-MCP-NUKE-019 negative controls, each rejected inside this passing test: a download that buffers the whole
18:     /// body before writing, a client with HttpClient's default 100 s total limit, an inactivity deadline that is never
19:     /// reset, no inactivity limit at all, and failures that do not name the URL.
20:     /// </summary>
21:     /// <param name="fault">Injected fault.</param>
22:     [Theory]
23:     [InlineData(Fault.BuffersWholeBody)]
24:     [InlineData(Fault.DefaultClientTimeout)]
25:     [InlineData(Fault.DeadlineNotReset)]
26:     [InlineData(Fault.NoInactivityLimit)]
27:     [InlineData(Fault.UnnamedFailure)]
28:     public async Task WrongDownload_IsRejected(Fault fault)
29:         => await Assert.ThrowsAnyAsync<Xunit.Sdk.XunitException>(
30:             () => ProvisioningDownloadContract.AssertDownloadAsync(new ScriptedDownload(fault))).ConfigureAwait(true);
31: 
32:     /// <summary>Faults injected into the scripted download for negative controls.</summary>
33:     public enum Fault
34:     {
35:         /// <summary>No fault: streams to disk, no total limit, the inactivity limit reset on every read.</summary>
36:         None,
37: 
38:         /// <summary>Reads the whole body into memory (HttpClient's default completion) before writing the file.</summary>
39:         BuffersWholeBody,
40: 
41:         /// <summary>Keeps HttpClient's default 100 s total limit.</summary>
42:         DefaultClientTimeout,
43: 
44:         /// <summary>Sets the inactivity deadline once for the whole transfer instead of after every read.</summary>
45:         DeadlineNotReset,
46: 
47:         /// <summary>Has no inactivity limit, so a stalled transfer waits forever.</summary>
48:         NoInactivityLimit,
49: 
50:         /// <summary>Fails without the URL in the message.</summary>
51:         UnnamedFailure,
52:     }
53: 
54:     /// <summary>Scripted download: the contract-derived behavior, with an optional injected fault.</summary>
55:     private sealed class ScriptedDownload(Fault fault) : IProvisioningDownload
56:     {
57:         /// <inheritdoc />
58:         public HttpClient CreateClient(HttpMessageHandler handler)
59:             => fault == Fault.DefaultClientTimeout
60:                 ? new HttpClient(handler, disposeHandler: false)
61:                 : new HttpClient(handler, disposeHandler: false) { Timeout = Timeout.InfiniteTimeSpan };
62: 
63:         /// <inheritdoc />
64:         public async Task DownloadAsync(
65:             HttpMessageHandler handler,
66:             Uri url,
67:             string destinationPath,
68:             TimeSpan inactivityLimit,
69:             CancellationToken cancellationToken)
70:         {
71:             using var client = CreateClient(handler);
72:             using var inactivity = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
73:             var limited = fault != Fault.NoInactivityLimit;
74:             if (limited)
75:                 inactivity.CancelAfter(inactivityLimit);
76:             try
77:             {
78:                 var completion = fault == Fault.BuffersWholeBody
79:                     ? HttpCompletionOption.ResponseContentRead
80:                     : HttpCompletionOption.ResponseHeadersRead;
81:                 using var response = await client.GetAsync(url, completion, inactivity.Token).ConfigureAwait(false);
82:                 if (fault == Fault.UnnamedFailure)
83:                     response.EnsureSuccessStatusCode();
84:                 else if (!response.IsSuccessStatusCode)
85:                     throw new HttpRequestException($"Download of {url} failed: the server answered {(int)response.StatusCode}.");
86: 
87:                 await using var source = await response.Content.ReadAsStreamAsync(inactivity.Token).ConfigureAwait(false);
88:                 await using var target = new FileStream(destinationPath, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize: 1, useAsync: true);
89:                 var buffer = new byte[81920];
90:                 while (true)
91:                 {
92:                     if (limited && fault != Fault.DeadlineNotReset)
93:                         inactivity.CancelAfter(inactivityLimit);
94:                     var read = await source.ReadAsync(buffer, inactivity.Token).ConfigureAwait(false);
95:                     if (read == 0)
96:                         break;
97:                     await target.WriteAsync(buffer.AsMemory(0, read), cancellationToken).ConfigureAwait(false);
98:                 }
99:             }
100:             catch (OperationCanceledException) when (inactivity.IsCancellationRequested && !cancellationToken.IsCancellationRequested && fault != Fault.UnnamedFailure)
101:             {
102:                 throw new TimeoutException($"Download of {url} stopped: no data arrived for {inactivityLimit}.");
103:             }
104:         }
105:     }
106: }
