271:     internal sealed class CapturingProcessSpawner(
272:         int exitCode,
273:         string outputBody = "",
274:         string stdout = "",
275:         string stderr = "",
276:         bool waitForCancellation = false) : IProcessSpawner
277:     {
278:         public ProcessStartInfo? StartInfo { get; private set; }
279: 
280:         public string? OutputLastMessagePath { get; private set; }
281: 
282:         public string? OutputSchemaPath { get; private set; }
283: 
284:         public string? OutputSchemaJson { get; private set; }
285: 
286:         public string? CapturedStandardInput => LastProcess?.StandardInputText;
287: 
288:         private FakeSpawnedProcess? LastProcess { get; set; }
289: 
290:         public ISpawnedProcess Spawn(ProcessStartInfo startInfo)
291:         {
292:             StartInfo = startInfo;
293:             OutputLastMessagePath = GetArgumentValue(startInfo, "-o");
294:             OutputSchemaPath = GetArgumentValue(startInfo, "--output-schema");
295:             if (!string.IsNullOrWhiteSpace(OutputSchemaPath) && File.Exists(OutputSchemaPath))
296:             {
297:                 OutputSchemaJson = File.ReadAllText(OutputSchemaPath, Encoding.UTF8);
298:             }
299: 
300:             if (!string.IsNullOrWhiteSpace(OutputLastMessagePath) && outputBody.Length > 0)
301:             {
302:                 File.WriteAllText(OutputLastMessagePath, outputBody, Encoding.UTF8);
303:             }
304: 
305:             LastProcess = new FakeSpawnedProcess(exitCode, stdout, stderr, waitForCancellation);
306:             return LastProcess;
307:         }
308: 
309:         public bool HasArgument(string name)
310:         {
311:             if (StartInfo is null)
312:                 return false;
313: 
314:             return StartInfo.ArgumentList.Any(argument => string.Equals(argument, name, StringComparison.Ordinal))
315:                 || StartInfo.ArgumentList.Any(argument => Regex.IsMatch(
316:                     argument,
317:                     "(^|\\s)" + Regex.Escape(name) + "(\\s|$)",
318:                     RegexOptions.CultureInvariant,
319:                     TimeSpan.FromMilliseconds(100)));
320:         }
321: 
322:         private static string? GetArgumentValue(ProcessStartInfo startInfo, string name)
323:         {
324:             for (var index = 0; index < startInfo.ArgumentList.Count - 1; index++)
325:             {
326:                 if (string.Equals(startInfo.ArgumentList[index], name, StringComparison.Ordinal))
327:                     return startInfo.ArgumentList[index + 1];
328:             }
329: 
330:             var pattern = Regex.Escape(name) + "\\s+(?:\"(?<quoted>[^\"]+)\"|(?<plain>\\S+))";
331:             foreach (var argument in startInfo.ArgumentList)
332:             {
333:                 var match = Regex.Match(argument, pattern, RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));
334:                 if (match.Success)
335:                     return match.Groups["quoted"].Success ? match.Groups["quoted"].Value : match.Groups["plain"].Value;
336:             }
337: 
338:             return null;
339:         }
340:     }
