34:     /// <summary>
35:     /// TR-MCP-QBRAIN-005: Projects QBrainAi and Mcp onto the Mcp section with live precedence.
36:     /// Command line wins over environment, which wins over file QBrainAi, which wins over file Mcp.
37:     /// Within a layer, QBrainAi wins per key. Sources added after this call still override projected keys.
38:     /// The projection recomputes when providers reload, so API writes are visible without a process restart.
39:     /// </summary>
40:     /// <param name="builder">Configuration root that already exposes the sources added so far.</param>
41:     public static void ProjectCanonicalSectionOverLegacy(IConfigurationBuilder builder)
42:     {
43:         ArgumentNullException.ThrowIfNull(builder);
44:         if (builder is not IConfigurationRoot root)
45:             throw new ArgumentException("The configuration builder must expose the sources added so far.", nameof(builder));
46: 
47:         if (root.Providers.Any(provider => provider is CanonicalSectionProjectionProvider))
48:             return;
49: 
50:         builder.Add(new CanonicalSectionProjectionSource(root));
51:     }
