53:     /// <summary>
54:     /// TR-MCP-QBRAIN-005: Builds a configuration whose root is the effective product section.
55:     /// When projection is installed, the snapshot matches command line, environment, then QBrainAi, then Mcp.
56:     /// Without projection, Mcp keys are copied first and QBrainAi keys overwrite them.
57:     /// </summary>
58:     public static IConfiguration GetEffectiveProductConfiguration(IConfiguration configuration)
59:     {
60:         ArgumentNullException.ThrowIfNull(configuration);
61:         if (TryGetProjection(configuration, out var projection))
62:             return projection.CreateProductConfiguration();
63: 
64:         var merged = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
65:         CopySection(configuration.GetSection("Mcp"), string.Empty, merged);
66:         CopySection(configuration.GetSection("QBrainAi"), string.Empty, merged);
67:         return new ConfigurationBuilder().AddInMemoryCollection(merged).Build();
68:     }
