70:     /// <summary>
71:     /// Binds a list from the effective product section. Workspace lists use the winning section as a whole
72:     /// so a QBrainAi entry cannot keep leftover fields from a different Mcp entry.
73:     /// </summary>
74:     public static List<T> BindEffectiveList<T>(IConfiguration configuration, string sectionKey)
75:     {
76:         ArgumentNullException.ThrowIfNull(configuration);
77:         ArgumentNullException.ThrowIfNull(sectionKey);
78:         if (TryGetProjection(configuration, out _))
79:             return GetEffectiveProductConfiguration(configuration).GetSection(sectionKey).Get<List<T>>() ?? [];
80: 
81:         var canonical = configuration.GetSection("QBrainAi:" + sectionKey);
82:         if (canonical.Exists())
83:             return canonical.Get<List<T>>() ?? [];
84: 
85:         return configuration.GetSection("Mcp:" + sectionKey).Get<List<T>>() ?? [];
86:     }
