91:     /// </summary>
92:     public static string? GetEffectiveMcpValue(IConfiguration configuration, string? instanceName, string key)
93:     {
94:         ArgumentNullException.ThrowIfNull(configuration);
95:         ArgumentNullException.ThrowIfNull(key);
96: 
97:         if (TryGetProjection(configuration, out var projection))
98:         {
99:             if (!string.IsNullOrWhiteSpace(instanceName)
100:                 && projection.TryGetProjected($"Instances:{instanceName}:{key}", out var projectedInstance))
101:                 return string.IsNullOrWhiteSpace(projectedInstance) ? null : projectedInstance;
102: 
103:             if (projection.TryGetProjected(key, out var projected))
104:                 return string.IsNullOrWhiteSpace(projected) ? null : projected;
105: 
106:             return null;
107:         }
108: 
109:         if (!string.IsNullOrWhiteSpace(instanceName))
110:         {
111:             var canonicalInstance = configuration[$"QBrainAi:Instances:{instanceName}:{key}"];
112:             if (!string.IsNullOrWhiteSpace(canonicalInstance))
113:                 return canonicalInstance;
114: 
