116:             if (!string.IsNullOrWhiteSpace(legacyInstance))
117:                 return legacyInstance;
118:         }
119: 
120:         var canonical = configuration[$"QBrainAi:{key}"];
121:         if (!string.IsNullOrWhiteSpace(canonical))
122:             return canonical;
123: 
124:         return configuration[$"Mcp:{key}"];
125:     }
