9: /// <summary>
10: /// Resolves effective MCP database-provider configuration and applies it to service registration.
11: /// </summary>
12: internal static class McpDatabaseConfigurationResolver
13: {
14:     private const string InMemoryDatabaseName = "mcp-tests";
15: 
16:     /// <summary>
17:     /// Adds the configured <see cref="McpDbContext"/> registration for the selected provider.
18:     /// </summary>
19:     /// <param name="services">Service collection receiving the DbContext registration.</param>
20:     /// <param name="configuration">Application configuration.</param>
21:     /// <param name="instanceName">Optional MCP instance name.</param>
22:     /// <param name="isTestEnvironment">Whether the current host environment is <c>Test</c>.</param>
23:     public static void AddConfiguredMcpDbContext(
24:         this IServiceCollection services,
25:         IConfiguration configuration,
26:         string? instanceName,
27:         bool isTestEnvironment)
28:     {
29:         ArgumentNullException.ThrowIfNull(services);
30:         ArgumentNullException.ThrowIfNull(configuration);
31: 
32:         if (isTestEnvironment && ShouldUseInMemoryDatabase(configuration, instanceName))
33:         {
34:             services.AddDbContext<McpDbContext>(options =>
35:             {
36:                 options.UseInMemoryDatabase(InMemoryDatabaseName);
37:                 options.EnableSensitiveDataLogging();
38:             }, ServiceLifetime.Scoped, ServiceLifetime.Scoped);
39:             return;
40:         }
41: 
42:         var runtimeOptions = ResolveRuntimeOptions(configuration, instanceName);
43:         var providerOptions = runtimeOptions.ProviderOptions;
44:         services.AddSingleton(runtimeOptions);
45:         services.AddSingleton(providerOptions);
46:         services.AddDbContext<McpDbContext>(options =>
47:         {
48:             McpDatabaseProviderFactory.Configure(options, providerOptions);
49:         }, ServiceLifetime.Scoped, ServiceLifetime.Scoped);
50:     }
51: 
52:     /// <summary>
53:     /// Resolves the configured provider and connection string to a normalized provider option set.
54:     /// </summary>
55:     /// <param name="configuration">Application configuration.</param>
56:     /// <param name="instanceName">Optional MCP instance name.</param>
57:     /// <returns>The resolved provider options.</returns>
58:     public static McpDatabaseProviderOptions ResolveProviderOptions(IConfiguration configuration, string? instanceName)
59:         => ResolveRuntimeOptions(configuration, instanceName).ProviderOptions;
60: 
61:     /// <summary>
62:     /// Resolves the configured provider, connection string, and native encryption settings into one runtime contract.
63:     /// </summary>
64:     /// <param name="configuration">Application configuration.</param>
65:     /// <param name="instanceName">Optional MCP instance name.</param>
66:     /// <returns>The resolved runtime options.</returns>
67:     public static McpDatabaseRuntimeOptions ResolveRuntimeOptions(IConfiguration configuration, string? instanceName)
68:     {
69:         ArgumentNullException.ThrowIfNull(configuration);
70: 
71:         var requestedProvider = ResolveRequestedProvider(configuration, instanceName);
72:         var strategy = McpDatabaseProviderFactory.ResolveStrategy(requestedProvider);
73:         var migrationsAssembly = GetEffectiveDatabaseValue(configuration, instanceName, "MigrationsAssembly")
74:             ?? McpInstanceResolver.GetEffectiveMcpValue(configuration, instanceName, "DatabaseMigrationsAssembly")
75:             ?? QBrainAi.Common.AgentCli.ProductEnvironment.GetLegacy("MCP_DATABASE_MIGRATIONS_ASSEMBLY");
76: 
77:         var connectionString = strategy.Kind switch
78:         {
79:             McpDatabaseProviderKind.Sqlite => ResolveSqliteConnectionString(configuration, instanceName),
80:             McpDatabaseProviderKind.PostgreSql => ResolvePostgreSqlConnectionString(configuration, instanceName),
81:             McpDatabaseProviderKind.SqlServer => ResolveSqlServerConnectionString(configuration, instanceName),
82:             _ => throw new InvalidOperationException($"Unsupported MCP database provider '{requestedProvider}'."),
83:         };
84: 
85:         var autoMigrateRaw = GetEffectiveDatabaseValue(configuration, instanceName, "AutoMigrate");
86:         if (autoMigrateRaw is not null && !bool.TryParse(autoMigrateRaw, out _))
87:             throw new InvalidOperationException("Mcp:Database:AutoMigrate must be true or false.");
88:         var autoMigrate = autoMigrateRaw is null || bool.Parse(autoMigrateRaw);
89: 
90:         return new McpDatabaseRuntimeOptions(
91:             McpDatabaseProviderFactory.CreateOptions(requestedProvider, connectionString, migrationsAssembly),
92:             ResolveEncryptionOptions(configuration, instanceName),
93:             autoMigrate);
94:     }
